CREATE COLUMN TABLE "TEST_AP"."OSCT" ("callTypeID" SMALLINT CS_INT NOT NULL , "Name" NVARCHAR(20) NOT NULL , "Descriptio" NCLOB MEMORY THRESHOLD 1000, "Active" NVARCHAR(1) DEFAULT 'Y', PRIMARY KEY ("callTypeID")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OSCT_NAME" ON "TEST_AP"."OSCT" ( "Name" ASC )